const test=require('node:test');
const assert=require('node:assert/strict');
const {runSerial}=require('../migration.cjs');
test('no overlap and indexed results',async()=>{
  let active=0,max=0;
  const events=[], items=['schema','index','view'];
  const values=await runSerial(items,async(item,index)=>{
    active++; max=Math.max(max,active); events.push('start:'+item);
    await Promise.resolve();
    events.push('end:'+item); active--;
    return index+':'+item;
  });
  assert.equal(max,1);
  assert.deepEqual(values,['0:schema','1:index','2:view']);
  assert.deepEqual(events,['start:schema','end:schema','start:index','end:index','start:view','end:view']);
  assert.deepEqual(items,['schema','index','view']);
});
test('first failure stops subsequent work',async()=>{
  const marker=new Error('index conflict'),started=[];
  await assert.rejects(runSerial([1,2,3],async value=>{
    started.push(value);
    if(value===2) throw marker;
    return value;
  }),error=>error===marker);
  assert.deepEqual(started,[1,2]);
  assert.deepEqual(await runSerial([],()=>{throw Error('unreachable');}),[]);
});

